-- MANUAL (not generated by Prisma). Prisma 5.22 cannot express partial
-- indexes, so this statement exists only here, never in schema.prisma
-- (Student.registrationNumber stays `String?` without @unique).
--
-- A registration number is unique across ALL teachers among students that are
-- not deleted (status 0 active, 1 inactive). Deleted students (status 2) are
-- outside the index, so their numbers can be reused; NULL numbers never clash.
--
-- Before applying, this must return no rows (otherwise the CREATE fails):
--   SELECT "registrationNumber", COUNT(*) FROM "Student"
--   WHERE "status" <> 2 AND "registrationNumber" IS NOT NULL
--   GROUP BY 1 HAVING COUNT(*) > 1;
--
-- Never remove it. Any later migration containing
--   DROP INDEX "Student_registrationNumber_not_deleted_key"
-- is a bug: see docs/student-registration-number-index.md.
-- Guarded by tests/students/registration-number-migration-guard.test.cjs.
-- ---------------------------------------------------------------------------
CREATE UNIQUE INDEX "Student_registrationNumber_not_deleted_key"
  ON "Student" ("registrationNumber")
  WHERE "status" <> 2;
